import unittest

from hourglass.timesheet import timesheet_rows
from hourglass.models import Shift, Span
from hourglass.errors import ProjectError


def make_shift(worker: str, start: int, end: int) -> Shift:
    return Shift(worker, "mon", Span(start * 60, end * 60))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        rows = timesheet_rows([
            make_shift("ann", 9, 10),
            make_shift("bob", 9, 12),
            make_shift("ann", 13, 14)
        ])
        self.assertEqual(rows, [
            "bob: 1 shifts, 3.0 hours",
            "ann: 2 shifts, 2.0 hours"
        ])

    def test_one_decimal(self):
        shift = Shift("ann", "tue", Span(540, 575))
        rows = timesheet_rows([shift])
        self.assertEqual(rows, ["ann: 1 shifts, 0.6 hours"])

    def test_empty_raises(self):
        with self.assertRaises(ProjectError):
            timesheet_rows([])

    def test_blank_worker_raises(self):
        with self.assertRaises(ProjectError):
            timesheet_rows([make_shift("  ", 9, 10)])
